window.MG_LAZY_DATA["data/lazy/resources/security-v26-024-2412d92bd5dd4a83.json"]={sha256:"2412d92bd5dd4a83362c3b8dc9353f41a30262c0dbcdbc3255b55acfa0d74685",value:{"sources":[{"id":"v26-case-236d191fe36a7161","url":"https://bind9.readthedocs.io/en/latest/reference.html","title":"BIND 9 Configuration Reference","titleEn":"BIND 9 Configuration Reference","publisher":"ISC","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"security-v26-024","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"security-v26-024","related":[{"id":"security-v26-025","referenceUrls":["https://www.rfc-editor.org/rfc/rfc7489.html"],"title":"DMARC：SPF、DKIM 與網域對齊證據","titleEn":"DMARC: SPF, DKIM and domain-alignment evidence","why":"用兩課的可觀察驗收條件比較模型邊界：4000與2000僅為負載模型；外部遞迴負例與內外名稱隔離均有可核對結果。 交付視圖/ACL矩陣、上游負載估算與zone發布檢查清單。","whyEn":"Compare model boundaries using observable acceptance criteria: Treat 4000 and 2000 only as load estimates and retain verifiable unauthorized-recursion and name-isolation results. Deliver view/ACL tests, upstream-load estimates and a zone-publication checklist.","difference":"以合成郵件列From、Return-Path、DKIM d=與各驗證結果；分開標示SPF通過、DKIM通過及對齊，不把單項pass直接當DMARC通過。","differenceEn":"Tabulate From, Return-Path, DKIM d= and results for synthetic mail; distinguish raw SPF/DKIM pass from alignment.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["理想化上游查詢數=總遞迴需求×(1−快取命中率)；快取命中高不表示ACL正確，安全與負載須分開驗證。 合成需求每分鐘40000筆、命中率90%；忽略預取、重試與單次查詢衍生多筆上游交換。 40000×(1−0.90)=4000筆上游查詢；命中率95%時為2000筆。","DMARC通過集合=已對齊SPF通過 OR 已對齊DKIM通過；聯集需扣重疊，並另處理轉寄與郵件清單的合法變形。 400封合成郵件中，300封SPF已對齊通過、280封DKIM已對齊通過，250封同時符合。 聯集300+280−250=330封，通過率82.5%；DKIM改320且重疊270時聯集350封、87.5%。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Ideal upstream query count equals recursive demand×(1−cache hit rate); high cache efficiency does not prove correct ACLs. Synthetic demand is 40000 requests/minute with 90% cache hit rate; ignore prefetch, retries and multi-exchange resolution. 40000×(1−0.90)=4000 upstream queries; a 95% hit rate gives 2000.","DMARC passing set is aligned SPF pass OR aligned DKIM pass; subtract overlap and separately examine legitimate forwarding/list transformations. Among 400 synthetic messages, 300 pass aligned SPF, 280 pass aligned DKIM and 250 pass both. Union is 300+280−250=330 messages or 82.5%; DKIM 320 and overlap 270 yield 350 or 87.5%.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"security-v26-034","referenceUrls":["https://documentation.wazuh.com/current/user-manual/index.html"],"title":"Wazuh FIM：基準、變更授權與完整性掃描","titleEn":"Wazuh FIM: baselines, authorized changes and integrity scans","why":"用兩課的可觀察驗收條件比較模型邊界：4000與2000僅為負載模型；外部遞迴負例與內外名稱隔離均有可核對結果。 交付視圖/ACL矩陣、上游負載估算與zone發布檢查清單。","whyEn":"Compare model boundaries using observable acceptance criteria: Treat 4000 and 2000 only as load estimates and retain verifiable unauthorized-recursion and name-isolation results. Deliver view/ACL tests, upstream-load estimates and a zone-publication checklist.","difference":"為測試設定目錄建立路徑、大小、內容雜湊與核准變更單；比較內容改變、只改mtime、檔案移除三種合成事件。","differenceEn":"Inventory path, size, content hash and approved change record for a test configuration directory; compare content changes, mtime-only changes and deletion.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["理想化上游查詢數=總遞迴需求×(1−快取命中率)；快取命中高不表示ACL正確，安全與負載須分開驗證。 合成需求每分鐘40000筆、命中率90%；忽略預取、重試與單次查詢衍生多筆上游交換。 40000×(1−0.90)=4000筆上游查詢；命中率95%時為2000筆。","順序讀取的理想掃描時間=總資料MiB/有效吞吐MiB每秒；metadata、雜湊CPU與小檔案開銷另算，雜湊變更不直接證明惡意。 2100個教學檔案各1MiB，假設有效掃描70MiB/秒。 2100/70=30秒；吞吐降至35MiB/秒時需60秒。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Ideal upstream query count equals recursive demand×(1−cache hit rate); high cache efficiency does not prove correct ACLs. Synthetic demand is 40000 requests/minute with 90% cache hit rate; ignore prefetch, retries and multi-exchange resolution. 40000×(1−0.90)=4000 upstream queries; a 95% hit rate gives 2000.","Ideal sequential scan time is total MiB divided by effective MiB/s; metadata, hashing CPU and small-file overhead are separate, and a hash change alone does not prove malice. There are 2100 teaching files of 1 MiB each, with assumed effective scanning throughput 70 MiB/s. 2100/70=30 seconds; throughput 35 MiB/s needs 60 seconds.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v26-case-bba5b35aff190db5","url":"https://www.rfc-editor.org/rfc/rfc7489.html","title":"RFC 7489: DMARC","titleEn":"RFC 7489: DMARC","publisher":"RFC Editor","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-7c9f3f6eb2fdd09b","url":"https://documentation.wazuh.com/current/user-manual/index.html","title":"Wazuh user manual","titleEn":"Wazuh user manual","publisher":"Wazuh","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
